#!/usr/bin/env python3
from __future__ import annotations

from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[2]


def read(path: str) -> str:
    return (ROOT / path).read_text()


def write(path: str, text: str) -> None:
    (ROOT / path).write_text(text)


def replace(path: str, old: str, new: str, *, count: int = 1) -> None:
    text = read(path)
    actual = text.count(old)
    if actual != count:
        raise SystemExit(f"{path}: expected {count} matches, found {actual}: {old[:100]!r}")
    write(path, text.replace(old, new, count))


def sub(path: str, pattern: str, replacement: str, *, count: int = 1) -> None:
    text = read(path)
    updated, actual = re.subn(pattern, replacement, text, count=count, flags=re.S)
    if actual != count:
        raise SystemExit(f"{path}: expected {count} regex matches, found {actual}: {pattern[:100]!r}")
    write(path, updated)


replace("packages/desktop-protocol/src/native-audio-host.ts", "export const nativeAudioHostProtocolVersion = 16", "export const nativeAudioHostProtocolVersion = 17")
