replace(coordinator, '''          Math.ceil(candidate.vstAutomationSegments.length / nativeInstrumentEventBatchSize),\n          1,''', '''          Math.ceil(candidate.vstAutomationSegments.length / nativeInstrumentEventBatchSize),\n          Math.ceil(candidate.processorAutomationEvents.length / nativeInstrumentEventBatchSize),\n          1,''', count=1)
